export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface Plan {
  minNights: number;
  maxNights: number;
  maxGuests: number;
  basePerNight: number;
  surchargePerNight: number;
  flatFee: number;
  perGuestFee?: number;
  minStayError?: string;
}

const PLANS: Record<string, Plan> = {
  standard: { minNights: 1, maxNights: 14, maxGuests: 2, basePerNight: 80, surchargePerNight: 30, flatFee: 0 },
  suite: { minNights: 1, maxNights: 21, maxGuests: 4, basePerNight: 150, surchargePerNight: 60, flatFee: 0, perGuestFee: 25 },
  villa: { minNights: 3, maxNights: 28, maxGuests: 8, basePerNight: 300, surchargePerNight: 120, flatFee: 500, minStayError: "villa minimum stay" },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const plan = PLANS[req.category as string];
  if (!plan) {
    return { ok: false, error: "unknown category" };
  }
  const nights = req.nights as number;
  const guests = req.guests as number;
  const season = req.season as string;

  if (nights < 1 || nights > plan.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (nights < plan.minNights) {
    return { ok: false, error: plan.minStayError ?? "bad nights" };
  }
  if (!Number.isInteger(guests) || guests < 1 || guests > plan.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }
  if (!Number.isInteger(nights)) {
    return { ok: false, error: "bad nights" };
  }

  const vip = req.coupon === "VIP";
  const discountEligible = vip || (req.loyaltyYears as number) >= 3;

  let total = plan.basePerNight * nights;
  if (season === "high") {
    total += plan.surchargePerNight * nights;
  }
  if (discountEligible) {
    total -= Math.floor(total / 10);
  }
  total += plan.flatFee;
  if (plan.perGuestFee && guests > 2) {
    total += plan.perGuestFee;
  }
  const policy = discountEligible ? "flex" : "strict";
  const line = req.category + ":" + String(nights) + "n:" + String(total) + ":" + policy;
  return { ok: true, total, policy, line };
}

