    if (!Number.isInteger(req.guests) || req.guests < 1 || req.guests > 2) return { ok: false, error: "bad guests" };
    if (req.season !== "low" && req.season !== "high") return { ok: false, error: "bad season" };
    let total = 80 * req.nights;
    if (req.season === "high") total = total + 30 * req.nights;
    if (req.loyaltyYears >= 3 || req.coupon === "VIP") total = total - Math.floor(total / 10);
    let policy = "strict";
    if (req.coupon === "VIP" || req.loyaltyYears > 2) policy = "flex";
    const line = "standard:" + String(req.nights) + "n:" + String(total) + ":" + policy;
    return { ok: true, total, policy, line };
  }
  if (req.category === "suite") {
    if (!Number.isInteger(req.nights) || req.nights < 1 || req.nights > 21) return { ok: false, error: "bad nights" };
    if (!Number.isInteger(req.guests) || req.guests < 1 || req.guests > 4) return { ok: false, error: "bad guests" };
    if (!(req.season === "low" || req.season === "high")) return { ok: false, error: "bad season" };
    let total = 150 * req.nights;
    if (req.season === "high") total = total + 60 * req.nights;
    if (req.coupon === "VIP" || req.loyaltyYears >= 3) total = total - Math.floor(total / 10);
    if (req.guests > 2) total = total + 25;
    let policy = "strict";
    if (!(req.loyaltyYears < 3) || req.coupon === "VIP") policy = "flex";
    const line = "suite:" + String(req.nights) + "n:" + String(total) + ":" + policy;
    return { ok: true, total, policy, line };
  }
  if (req.category === "villa") {
    if (!Number.isInteger(req.nights) || req.nights < 1 || req.nights > 28) return { ok: false, error: "bad nights" };
    if (req.nights < 3) return { ok: false, error: "villa minimum stay" };
    if (!Number.isInteger(req.guests) || req.guests < 1 || req.guests > 8) return { ok: false, error: "bad guests" };
    if (req.season !== "low" && req.season !== "high") return { ok: false, error: "bad season" };
    let total = 300 * req.nights;
    if (req.season === "high") total = total + 120 * req.nights;
    if (req.loyaltyYears > 2 || req.coupon === "VIP") total = total - Math.floor(total / 10);
    total = total + 500;
    let policy = "strict";
    if (req.coupon === "VIP" || !(req.loyaltyYears < 3)) policy = "flex";
    const line = "villa:" + String(req.nights) + "n:" + String(total) + ":" + policy;
    return { ok: true, total, policy, line };
  }
  return { ok: false, error: "unknown category" };
}
